{
  "hooks": {
    "SessionStart": [
      {
        "matcher": "startup|resume|clear|compact",
        "hooks": [
          {
            "type": "command",
            "command": "python3 /home/codexloop/codex-loop-s-f2/hooks/subagent_lifecycle.py --event SessionStart",
            "commandWindows": "py -3 \"\\\\wsl.localhost\\Ubuntu\\home\\codexloop\\codex-loop-s-f2\\hooks\\subagent_lifecycle.py\" --event SessionStart",
            "timeout": 30,
            "statusMessage": "Reconciling stale subagent lifecycle records"
          }
        ]
      }
    ],
    "SubagentStart": [
      {
        "matcher": ".*",
        "hooks": [
          {
            "type": "command",
            "command": "python3 /home/codexloop/codex-loop-s-f2/hooks/subagent_lifecycle.py --event SubagentStart",
            "commandWindows": "py -3 \"\\\\wsl.localhost\\Ubuntu\\home\\codexloop\\codex-loop-s-f2\\hooks\\subagent_lifecycle.py\" --event SubagentStart",
            "timeout": 30,
            "statusMessage": "Recording and naming subagent start"
          }
        ]
      }
    ],
    "SubagentStop": [
      {
        "matcher": ".*",
        "hooks": [
          {
            "type": "command",
            "command": "python3 /home/codexloop/codex-loop-s-f2/hooks/subagent_lifecycle.py --event SubagentStop",
            "commandWindows": "py -3 \"\\\\wsl.localhost\\Ubuntu\\home\\codexloop\\codex-loop-s-f2\\hooks\\subagent_lifecycle.py\" --event SubagentStop",
            "timeout": 30,
            "statusMessage": "Marking subagent terminal and queuing host close"
          }
        ]
      }
    ],
    "Stop": [
      {
        "matcher": ".*",
        "hooks": [
          {
            "type": "command",
            "command": "python3 /home/codexloop/codex-loop-s-f2/hooks/subagent_lifecycle.py --event Stop",
            "commandWindows": "py -3 \"\\\\wsl.localhost\\Ubuntu\\home\\codexloop\\codex-loop-s-f2\\hooks\\subagent_lifecycle.py\" --event Stop",
            "timeout": 30,
            "statusMessage": "Cascading parent Stop into lifecycle cancellation requests"
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": ".*",
        "hooks": [
          {
            "type": "command",
            "command": "python3 /home/codexloop/codex-loop-s-f2/hooks/sol_tool_gate_router.py",
            "commandWindows": "py -3 \"\\\\wsl.localhost\\Ubuntu\\home\\codexloop\\codex-loop-s-f2\\hooks\\sol_tool_gate_router.py\"",
            "timeout": 10,
            "statusMessage": "Sol tool gate: L0 work must be dispatched"
          },
          {
            "type": "command",
            "command": "python3 /home/codexloop/codex-loop-s-f2/hooks/subagent_lifecycle.py --event PreToolUse",
            "commandWindows": "py -3 \"\\\\wsl.localhost\\Ubuntu\\home\\codexloop\\codex-loop-s-f2\\hooks\\subagent_lifecycle.py\" --event PreToolUse",
            "timeout": 10,
            "statusMessage": "Recording semantic task name before subagent spawn"
          }
        ]
      }
    ]
  }
}
